import { recurrenceMaterializer } from './recurrenceMaterializer.js';
import { reminderEvaluator } from './reminderEvaluator.js';

Export async function resumeReconciliation({ stateAdapter, orchestrationAdapter, notificationAdapter, currentTime }) per SPEC §6.1 + §8.5.

Behavior:
1. Call orchestrationAdapter.onResume(currentTime) — informational.
2. Load active recurring task definitions:
   const allDefs = await stateAdapter.listTaskDefinitions({ status: 'active' });
   const recurringDefs = allDefs.filter(d => d['ftm:schedule']['ftm:scheduleType'] === 'recurring');
3. Load all task instances:
   const allInstances = await stateAdapter.listTaskInstances();
4. Call recurrenceMaterializer:
   const { toCreate, skipped } = recurrenceMaterializer(recurringDefs, allInstances, currentTime);
5. For each instance in toCreate:
   await stateAdapter.saveTaskInstance(instance);
   orchestrationAdapter.scheduleAt(instance['ftm:dueAt']['@value'], () => { /* placeholder reminder trigger; wired in Phase 4 */ });
6. Re-evaluate all pending instances where dueAt <= currentTime:
   const updatedInstances = await stateAdapter.listTaskInstances();
   const pendingDue = updatedInstances.filter(i => i['ftm:completionState']['ftm:status'] === 'pending' && i['ftm:dueAt']['@value'] <= currentTime);
   For each pending-due instance:
     const def = await stateAdapter.getTaskDefinition(instance['ftm:taskDefinition']);
     const verdict = reminderEvaluator(instance, def, currentTime);
     if (verdict.shouldRemind) {
       await notificationAdapter.send({ recipientUserId: instance['ftm:assignedTo'], title: def['ftm:title'], body: def['ftm:description'] ?? '', deepLinkUri: 'ftm://instance/' + instance['@id'].split(':').pop(), requestForegroundDisplay: true });
     }
7. Return { toCreate: toCreate.length, skipped };

No Phase 4 reminderSummary updates here (that flow lives in Phase 4 §8.2 reminder-trigger). Document this scoping in JSDoc.

