describe('3.2 InMemoryStateAdapter - §5.1 LWW conflict resolution', () => {
  test('higher clientSequence wins: save seq=1 then seq=2; get returns seq=2 entity')
  test('lower clientSequence loses: save seq=2 then seq=1; get returns seq=2 entity (unchanged)')
  test('equal clientSequence, later updatedAt wins: save seq=1 ts=A then seq=1 ts=B (B later); get returns B-version')
  test('equal clientSequence, equal updatedAt: incoming wins (idempotent re-save)')
  test('same LWW rules apply to saveTaskDefinition (operator I7: ignore §3.2 immutability; apply LWW symmetrically)')
